from pathlib import Path
p=Path('src/components/learning/TeacherWorksheetStudio.tsx')
s=p.read_text().replace('import {NUCLEAR_LESSONS', 'import {WORKSHEET_RUBRIC,WORKSHEET_RUBRIC_LEVELS} from "@/lib/worksheet-instructions";\nimport {NUCLEAR_LESSONS')
s=s.replace('const [busy,setBusy]', 'const [previous,setPrevious]=useState<GuidedWorksheetDraft|null>(null);\n const [busy,setBusy]')
s=s.replace('draftStore.update({...draft,...changes});', 'draftStore.update({...draft,...changes,...(changes.selection?{selection:changes.selection.slice().sort((a,b)=>WORKSHEET_PHASES.indexOf(a.phase)-WORKSHEET_PHASES.indexOf(b.phase))}:{})});')
s=s.replace('function sample(lesson:string){draftStore.update', 'function sample(lesson:string){setPrevious(draft);draftStore.update')
s=s.replace('if(!teacher)for(const {question:q}', 'for(const {question:q}')
s=s.replace('phaseTasks:draft.tasks,phaseResources:resources,', 'phaseTasks:draft.tasks,phaseResources:resources,phaseDetails:draft.phases,')
s=s.replace('<p>Phiếu mẫu đã có câu hỏi và hướng dẫn. Chọn bài, sửa những phần cần thay đổi rồi xuất phiếu cho học sinh và đáp án riêng cho giáo viên.</p>', '<p>Phiếu có ba phần: hướng dẫn sử dụng, nhiệm vụ học sinh thực hiện qua ba pha và rubrics đánh giá. Chọn bài, chỉnh phiếu rồi tải Word.</p>')
s=s.replace('<button className="btn primary" onClick={()=>move(1)}>Tiếp tục: chỉnh phiếu</button>', '<div className="book-actions">{previous&&<button className="btn" onClick={()=>{draftStore.update(previous);setPrevious(null);setNotice("Đã khôi phục phiếu trước khi đổi mẫu.");}}>Khôi phục phiếu trước khi đổi mẫu</button>}<button className="btn primary" onClick={()=>move(1)}>Tiếp tục: chỉnh phiếu</button></div>')
s=s.replace('câu hỏi vẫn giữ nội dung đang có trong ngân hàng.</p>', 'câu hỏi vẫn giữ nội dung đang có trong ngân hàng. Khi thay câu hỏi, chỉnh hướng dẫn và sản phẩm cho đúng nhiệm vụ mới.</p>')
s=s.replace('<label>{"Hướng dẫn "+WORKSHEET_PHASE_LABELS[phase]', '''<details className="workflow-details"><summary>Mục tiêu, thời gian và sản phẩm của pha</summary><label>Thời gian dự kiến (phút)<input type="number" min={5} max={60} value={draft.phases[phase].minutes} onChange={e=>patch({phases:{...draft.phases,[phase]:{...draft.phases[phase],minutes:Number(e.target.value)}}})}/></label>{([['objective','Mục tiêu của pha'],['product','Sản phẩm học sinh phải hoàn thành'],['criteria','Tiêu chí tự kiểm tra']] as const).map(([field,label])=><label key={field}>{label}<textarea rows={2} maxLength={4000} value={draft.phases[phase][field]} onChange={e=>patch({phases:{...draft.phases,[phase]:{...draft.phases[phase],[field]:e.target.value}}})}/></label>)}</details><label>{"Hướng dẫn "+WORKSHEET_PHASE_LABELS[phase]''')
a=s.index('<div className="workflow-document">')
b=s.index('</div>{errors.length?',a)+len('</div>')
s=s[:a]+'''<div className="workflow-document"><h4>{draft.title}</h4><p>{draft.lesson+" · "+NUCLEAR_LESSONS[draft.lesson as keyof typeof NUCLEAR_LESSONS]}</p>
   <section><h4>1. Hướng dẫn sử dụng phiếu học tập</h4><p>Hoàn thành phần chuẩn bị trước khi đến lớp. Giữ phiếu để trao đổi trong giờ học và tự làm phần vận dụng sau giờ học.</p><strong>Mục tiêu</strong><p className="workflow-multiline">{draft.objective}</p>{WORKSHEET_PHASES.map(phase=><p key={phase}><strong>{WORKSHEET_PHASE_LABELS[phase]+": "}</strong>{draft.phases[phase].minutes} phút. {draft.phases[phase].product}</p>)}<p>Đọc nhiệm vụ, làm câu hỏi trong khung trả lời và ghi căn cứ của cách làm. Xem rubrics ở phần 3 trước khi làm. Mỗi bạn hoàn thiện bài riêng sau khi thảo luận nhóm; nộp phiếu theo thời hạn giáo viên giao.</p>{WORKSHEET_PHASES.map(phase=>resources[phase].map(r=><p key={r.id}>{WORKSHEET_PHASE_LABELS[phase]+" · "}<a href={"/hoc-lieu?resource="+encodeURIComponent(r.id)} target="_blank" rel="noreferrer">{r.title} ↗</a></p>))}</section>
   <section><h4>2. Phiếu học tập cho học sinh</h4>{WORKSHEET_PHASES.map((phase,index)=><section className="workflow-phase" key={phase}><h4>{"Pha "+(index+1)+" · "+WORKSHEET_PHASE_LABELS[phase]+" · "+draft.phases[phase].minutes+" phút"}</h4><p><strong>Mục tiêu: </strong>{draft.phases[phase].objective}</p><strong>Việc cần làm</strong><p className="workflow-multiline">{draft.tasks[phase]}</p>{draft.selection.map((s,i)=>{const q=bank.find(q=>q.id===s.id);return s.phase===phase&&q?<div className="workflow-question" key={s.id}><strong>Câu {i+1}</strong><QuestionContent q={q}/>{audience==="teacher"?<QuestionContent q={q} answer/>:<p className="worksheet-write-space">Bài làm của em:<br/>....................................................................<br/>....................................................................</p>}</div>:null;})}<p><strong>Sản phẩm cần hoàn thành: </strong>{draft.phases[phase].product}</p><p><strong>Tự kiểm tra: </strong>{draft.phases[phase].criteria}</p>{audience==="student"&&<p className="worksheet-write-space">Điều chưa hiểu, điều đã sửa hoặc cách kiểm tra:<br/>....................................................................</p>}</section>)}</section>
   <section><h4>3. Rubrics đánh giá</h4><p>Học sinh tự chọn một mức cho từng tiêu chí. Giáo viên đối chiếu bài làm, ghi mức đánh giá và hướng dẫn sửa.</p><div className="workflow-table-scroll"><table className="workflow-rubric"><thead><tr><th>Tiêu chí</th>{WORKSHEET_RUBRIC_LEVELS.map(level=><th key={level}>{level}</th>)}</tr></thead><tbody>{WORKSHEET_RUBRIC.map(r=><tr key={r.criterion}><th>{r.criterion}<small>{WORKSHEET_PHASE_LABELS[r.phase as WorksheetPhase]}</small></th>{r.levels.map(level=><td key={level}>{level}</td>)}</tr>)}</tbody></table></div>{WORKSHEET_RUBRIC.map(r=><p key={r.criterion}>{r.criterion}: Học sinh chọn mức ....... Giáo viên chọn mức .......</p>)}<p className="worksheet-write-space">Nội dung cần sửa và cách sửa: ....................................................</p></section>
  </div>'''+s[b:]
s=s.replace('Đủ ba pha, có hướng dẫn, yêu cầu cần đạt và', 'Đủ ba phần, có nhiệm vụ cho ba pha, rubrics, yêu cầu cần đạt và')
p.write_text(s)
